solution:
fn read_u32(ptr: *Byte, offset: Int) -> Int
  requires: ptr != null;
  requires: offset >= 0;
  requires: offset + 4 <= 1024;  // Bounded
{
  let b0 = ptr[offset] as Int;
  let b1 = ptr[offset + 1] as Int;
  let b2 = ptr[offset + 2] as Int;
  let b3 = ptr[offset + 3] as Int;
  return b0 | (b1 << 8) | (b2 << 16) | (b3 << 24);
}

fn main() -> Int {
  let data = [0x01, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00];
  return read_u32(&data[0], 0);
}
